// Some portions generated by Co-Pilot
"use client";

import React from "react";
import { useSearchParams } from "next/navigation";
import { useTranslations } from "next-intl";
import { Link } from "@/i18n/navigation";
import { FiArrowLeft } from "react-icons/fi";
import ReleaseNotesRender from "@/components/Content/ReleaseNotes";
import ReleaseNotesVersionSelector from "@/components/Content/ReleaseNotesVersionSelector";

interface AvailableReleases {
  available_lts_releases: number[];
  available_releases: number[];
  most_recent_feature_release: number;
  most_recent_feature_version: number;
  most_recent_lts: number;
  tip_version: number;
}

interface ReleaseNotesPageClientProps {
  availableReleases: AvailableReleases;
}

const ReleaseNotesPageClient: React.FC<ReleaseNotesPageClientProps> = ({
  availableReleases,
}) => {
  const searchParams = useSearchParams();
  const t = useTranslations("ModernPages.release-notes");
  const version = searchParams.get("version");

  // If no version is specified, show the version selector
  if (!version) {
    return (
      <ReleaseNotesVersionSelector
        availableVersions={availableReleases.available_releases}
        availableLTSVersions={availableReleases.available_lts_releases}
      />
    );
  }

  // If a version is specified, show the release notes
  return (
    <>
      <div className="mx-auto max-w-7xl px-6 pt-8 sm:px-8">
        <Link
          href="/temurin/release-notes"
          className="inline-flex items-center gap-2 text-sm text-[#ff91b7] hover:text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
        >
          <FiArrowLeft aria-hidden="true" /> {t("back")}
        </Link>
      </div>
      <ReleaseNotesRender key={version} />
    </>
  );
};

export default ReleaseNotesPageClient;
